function removePerson(state,id){state.people=state.people.filter(p=>p.id!==id);state.unions=state.unions.filter(u=>u.personA!==id&&u.personB!==id);const unionIds=new Set(state.unions.map(u=>u.id));state.descentLinks=state.descentLinks.filter(l=>l.childId!==id&&!(l.sourceType==='person'&&l.sourceId===id)&&(l.sourceType!=='union'||unionIds.has(l.sourceId)));state.emotionalLinks=state.emotionalLinks.filter(l=>l.personA!==id&&l.personB!==id);state.households.forEach(h=>{h.memberIds=h.memberIds.filter(x=>x!==id);});delete state.childResponse.assignments[id];delete state.childResponse.omitted[id];delete state.childResponse.explanations[id];state.childResponse.order=state.childResponse.order.filter(x=>x!==id);return state;}
function normalizeUnionStatus(value){return value==='couple'?'marriage':['marriage','separated','divorced','free'].includes(value)?value:'marriage';}
function normalizeUnionOffsets(value={}){return {marriage:clamp(finite(value.marriage??value.label,0),-800,800),break:clamp(finite(value.break,0),-800,800),divorce:clamp(finite(value.divorce,0),-800,800)};}
