function assertHumanUnion(state,aId,bId){const a=getPerson(state,aId),b=getPerson(state,bId);if(!a||!b||aId===bId)throw new Error('Una unión necesita dos personas diferentes.');if(!isHuman(a)||!isHuman(b))throw new Error('Las mascotas no pueden formar uniones humanas o de pareja.');}
