function updateUnion(state,id,patch={}){const u=getUnion(state,id);if(!u)return null;const next={...u,...patch,id};assertHumanUnion(state,next.personA,next.personB);if(state.unions.some(x=>x.id!==id&&pairKey(x.personA,x.personB)===pairKey(next.personA,next.personB)))throw new Error('Esta unión ya existe.');Object.assign(u,{id,personA:next.personA,personB:next.personB,...normalizeUnionInput(next)});return u;}
function removeUnion(state,id){state.unions=state.unions.filter(u=>u.id!==id);state.descentLinks=state.descentLinks.filter(l=>!(l.sourceType==='union'&&l.sourceId===id));return state;}
function sourceParentIds(state,sourceType,sourceId){if(sourceType==='person')return getPerson(state,sourceId)?[sourceId]:[];const u=getUnion(state,sourceId);return u?[u.personA,u.personB]:[];}
