function addDescentLink(state,input={}){const sourceType=input.sourceType==='union'?'union':'person';const parents=sourceParentIds(state,sourceType,input.sourceId),child=getPerson(state,input.childId);if(!parents.length||!child)throw new Error('Selecciona un origen y una hija o hijo válidos.');if(!isHuman(child)||parents.some(id=>!isHuman(getPerson(state,id))))throw new Error('Las mascotas no forman enlaces de filiación humana.');if(parents.includes(input.childId))throw new Error('No se permite un autoenlace parental.');if(state.descentLinks.some(l=>l.sourceType===sourceType&&l.sourceId===input.sourceId&&l.childId===input.childId))throw new Error('Esta filiación ya existe.');for(const parentId of parents){if(hasAncestryPath(state,input.childId,parentId))throw new Error('No se puede crear un ciclo parental.');}const l={id:String(input.id||uid('descent')),sourceType,sourceId:input.sourceId,childId:input.childId,type:['biological','adoptive','care'].includes(input.type)?input.type:'biological'};state.descentLinks.push(l);return l;}
