function addEmotionalLink(state,input={}){if(!getPerson(state,input.personA)||!getPerson(state,input.personB)||input.personA===input.personB)throw new Error('Selecciona dos personas diferentes.');const type=EMOTION_ALIASES[input.type]||'close';if(state.emotionalLinks.some(l=>pairKey(l.personA,l.personB)===pairKey(input.personA,input.personB)&&l.type===type))throw new Error('Esta relación ya existe.');const l={id:String(input.id||uid('emotion')),personA:input.personA,personB:input.personB,type};state.emotionalLinks.push(l);return l;}
