function computeUnionGeometry(state,unionOrId){const u=typeof unionOrId==='string'?getUnion(state,unionOrId):unionOrId;if(!u)return null;const a=getPerson(state,u.personA),b=getPerson(state,u.personB);if(!a||!b)return null;const left=a.x<=b.x?a:b,right=left===a?b:a,midY=(left.y+right.y)/2;return {unionId:u.id,leftId:left.id,rightId:right.id,x1:left.x,y1:left.y,x2:right.x,y2:right.y,midX:(left.x+right.x)/2,midY,main:{x1:left.x,y1:midY,x2:right.x,y2:midY},connectors:[{x1:left.x,y1:left.y,x2:left.x,y2:midY},{x1:right.x,y1:right.y,x2:right.x,y2:midY}]};}
