function legendLine(type){if(type==='close')return '<svg aria-hidden="true"><path d="M2 5H44M2 11H44" stroke="#b34747" stroke-width="2"/></svg>';if(type==='fused')return '<svg aria-hidden="true"><path d="M2 3H44M2 8H44M2 13H44" stroke="#b34747" stroke-width="2"/></svg>';if(type==='distant')return '<svg aria-hidden="true"><path d="M2 8H44" stroke="#b34747" stroke-width="2.5" stroke-dasharray="3 7"/></svg>';if(type==='conflict')return '<svg aria-hidden="true"><path d="M2 8l5-5 5 10 5-10 5 10 5-10 5 10 5-10 5 5" fill="none" stroke="#b34747" stroke-width="2"/></svg>';if(type==='fusedConflict')return '<svg aria-hidden="true"><path d="M2 3H44M2 13H44M2 8l5-4 5 8 5-8 5 8 5-8 5 8 5-8 5 4" fill="none" stroke="#b34747" stroke-width="2"/></svg>';return '<svg aria-hidden="true"><path d="M2 8H44M20 2l-4 12M28 2l-4 12" stroke="#b34747" stroke-width="2"/></svg>';}
function legendHtml(professional=true){let html='<strong class="legend-title">Leyenda estructural</strong><span><svg aria-hidden="true"><path d="M2 8H44" stroke="#315b57" stroke-width="3"/></svg>Matrimonio / filiación biológica</span><span><svg aria-hidden="true"><path d="M2 8H44" stroke="#315b57" stroke-width="3" stroke-dasharray="12 8"/></svg>Unión libre</span><span><svg aria-hidden="true"><path d="M2 8H44" stroke="#315b57" stroke-width="3" stroke-dasharray="8 5"/></svg>Adopción</span><span><svg aria-hidden="true"><path d="M2 8H44" stroke="#315b57" stroke-width="3" stroke-dasharray="2 6"/></svg>Cuidado</span><span>🐕 Mascota</span>';if(professional){html+='<span>◎ Persona identificada</span><span>✕ Fallecimiento</span><strong class="legend-title">Relaciones emocionales (descriptivas)</strong>';Object.keys(LABELS.emotion).forEach(type=>{html+=`<span>${legendLine(type)}${LABELS.emotion[type]}</span>`;});}return html;}

var libraryState=typeof window!=='undefined'?loadLibrary():createLibrary();
var currentGenogramId=libraryState.currentId;
var appState=currentGenogramId?(libraryState.items.find(item=>item.id===currentGenogramId)?.state||createInitialState()):createInitialState();
let selectedPersonId=null,selectedAnnotationId=null,selectedUnionElement=null,currentCategory='todas',pendingMiniature=null,pendingOmitted=false,adultSum=0,dragState=null;
const $=id=>document.getElementById(id);
function showScreen(id){document.querySelectorAll('.screen').forEach(el=>el.classList.add('hidden'));$(id).classList.remove('hidden');window.scrollTo(0,0);}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200);}
function currentRecord(){return libraryState.items.find(item=>item.id===currentGenogramId)||null;}
function persist(){if(!currentGenogramId)return false;const updated=updateGenogramInLibrary(libraryState,currentGenogramId,appState);libraryState=updated.library;return saveLibrary(libraryState);}
function formatModified(value){try{return new Intl.DateTimeFormat('es',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}catch(_){return value;}}
function renderLibrary(){const host=$('genogram-library'),record=currentRecord();host.innerHTML=libraryState.items.map(item=>`<article class="library-item ${item.id===currentGenogramId?'active':''}"><div><strong>${escapeHtml(item.name)}</strong><small>Modificado: ${escapeHtml(formatModified(item.updatedAt))}</small></div><div class="library-actions"><button class="button secondary" type="button" data-library-action="open" data-id="${escapeHtml(item.id)}">${item.id===currentGenogramId?'Abierto':'Abrir'}</button><button class="button danger" type="button" data-library-action="delete" data-id="${escapeHtml(item.id)}" aria-label="Eliminar ${escapeHtml(item.name)}">Eliminar</button></div></article>`).join('')||'<p class="muted">Todavía no hay genogramas guardados.</p>';$('current-genogram').textContent=record?`Actual: ${record.name}`:'Crea o abre un genograma para continuar.';$('choose-professional').disabled=!record;$('choose-child').disabled=!record;$('rename-genogram-name').value=record?.name||'';$('genogram-date').value=record?.state?.genogramDate||'';}
function openGenogram(id){const record=libraryState.items.find(item=>item.id===id);if(!record)return false;currentGenogramId=id;libraryState.currentId=id;appState=sanitizeState(record.state);selectedPersonId=null;selectedAnnotationId=null;selectedUnionElement=null;saveLibrary(libraryState);renderLibrary();showScreen('welcome-screen');return true;}
function createAndOpenGenogram(name,state=createInitialState()){const added=addGenogramToLibrary(libraryState,name,state);libraryState=added.library;currentGenogramId=added.record.id;appState=sanitizeState(added.record.state);saveLibrary(libraryState);renderLibrary();return added.record;}
function personOptions(selected='',humansOnly=false){return '<option value="">Selecciona…</option>'+appState.people.filter(p=>!humansOnly||isHuman(p)).map(p=>`<option value="${escapeHtml(p.id)}" ${p.id===selected?'selected':''}>${escapeHtml(p.name)}${p.kind==='pet'?' · mascota':''}</option>`).join('');}
function sourceOptions(selected=''){const people=appState.people.filter(isHuman).map(p=>`<option value="person:${escapeHtml(p.id)}" ${selected===`person:${p.id}`?'selected':''}>Una persona · ${escapeHtml(p.name)}</option>`).join('');const unions=appState.unions.map(u=>`<option value="union:${escapeHtml(u.id)}" ${selected===`union:${u.id}`?'selected':''}>Unión · ${escapeHtml(getPerson(appState,u.personA)?.name||'?')} + ${escapeHtml(getPerson(appState,u.personB)?.name||'?')}</option>`).join('');return `<option value="">Selecciona…</option><optgroup label="Uniones">${unions}</optgroup><optgroup label="Progenitor individual">${people}</optgroup>`;}
function refreshSelects(){['union-a','union-b','descent-child'].forEach(id=>{const old=$(id).value;$(id).innerHTML=personOptions(old,true);});['emotion-a','emotion-b'].forEach(id=>{const old=$(id).value;$(id).innerHTML=personOptions(old,false);});const old=$('descent-source').value;$('descent-source').innerHTML=sourceOptions(old);$('household-members').innerHTML=appState.people.map(p=>`<label><input type="checkbox" value="${escapeHtml(p.id)}"> ${escapeHtml(p.name)}</label>`).join('')||'<p class="muted">Añade personas primero.</p>';}
function recordHtml(main,sub,id,kind,editable=false,selected=false){return `<div class="record ${selected?'selected':''}" data-record-id="${escapeHtml(id)}"><div><strong>${escapeHtml(main)}</strong><small>${escapeHtml(sub)}</small></div><div class="record-actions">${editable?`<button class="icon-button" data-action="edit-${kind}" data-id="${escapeHtml(id)}" aria-label="Editar ${escapeHtml(main)}">✎</button>`:''}<button class="icon-button" data-action="delete-${kind}" data-id="${escapeHtml(id)}" aria-label="Eliminar ${escapeHtml(main)}">×</button></div></div>`;}
function sourceName(l){if(l.sourceType==='union'){const u=getUnion(appState,l.sourceId);return u?`${getPerson(appState,u.personA)?.name||'?'} + ${getPerson(appState,u.personB)?.name||'?'}`:'Unión inexistente';}return getPerson(appState,l.sourceId)?.name||'?';}
function renderLists(){
  $('people-list').innerHTML=appState.people.map(p=>recordHtml((p.identified?'◎ ':'')+(p.kind==='pet'?'🐕 ':'')+p.name,(p.kind==='pet'?(p.species||'Mascota'):(p.role||'Sin rol'))+(p.age!==null?' · '+p.age+' años':'')+(p.deceased?' · Fallecido/a':'')+(p.birthDate?' · nac. '+p.birthDate:'')+(p.deceased&&p.deathDate?' · fall. '+p.deathDate:''),p.id,'person',true,p.id===selectedPersonId)).join('')||'<p class="muted">Todavía no hay personas ni mascotas.</p>';
  $('union-list').innerHTML=appState.unions.map(u=>recordHtml((getPerson(appState,u.personA)?.name||'?')+' — '+(getPerson(appState,u.personB)?.name||'?'),LABELS.union[u.status]+(u.marriageDate?' · m '+u.marriageDate:'')+(u.divorceDate?' · d '+u.divorceDate:''),u.id,'union',true,selectedUnionElement?.unionId===u.id)).join('')||'<p class="muted">Sin uniones.</p>';
  $('descent-list').innerHTML=appState.descentLinks.map(l=>recordHtml(sourceName(l)+' → '+(getPerson(appState,l.childId)?.name||'?'),LABELS.descent[l.type],l.id,'descent')).join('')||'<p class="muted">Sin filiaciones.</p>';
  $('emotion-list').innerHTML=appState.emotionalLinks.map(l=>recordHtml((getPerson(appState,l.personA)?.name||'?')+' ↔ '+(getPerson(appState,l.personB)?.name||'?'),LABELS.emotion[l.type],l.id,'emotion')).join('')||'<p class="muted">Sin relaciones emocionales.</p>';
  $('household-list').innerHTML=appState.households.map(h=>recordHtml(h.name,h.memberIds.map(id=>getPerson(appState,id)?.name).filter(Boolean).join(', '),h.id,'household')).join('')||'<p class="muted">Sin hogares.</p>';
  $('annotation-list').innerHTML=appState.annotations.map(a=>recordHtml(a.text,'Texto profesional independiente',a.id,'annotation',true,a.id===selectedAnnotationId)).join('')||'<p class="muted">Sin textos independientes.</p>';
}
function renderValidation(){const v=validateGraph(appState),el=$('validation-summary');el.classList.toggle('has-errors',!v.valid);el.textContent=v.errors.length?`Revisa: ${v.errors.join(' ')}`:v.warnings.length?`Estructura válida. ${v.warnings.join(' ')}`:'Estructura válida. Guardado local en este navegador y dispositivo.';return v;}
function attachCanvasInteractions(svg){if(!svg||svg.dataset.interactive!=='true')return;svg.querySelectorAll('[data-person-id]').forEach(node=>{node.addEventListener('pointerdown',e=>startCanvasDrag(e,'person',node.dataset.personId));node.addEventListener('click',()=>selectCanvasItem('person',node.dataset.personId));node.addEventListener('keydown',handleCanvasKey)});svg.querySelectorAll('[data-annotation-id]').forEach(node=>{node.addEventListener('pointerdown',e=>startCanvasDrag(e,'annotation',node.dataset.annotationId));node.addEventListener('click',()=>selectCanvasItem('annotation',node.dataset.annotationId));node.addEventListener('keydown',handleCanvasKey)});svg.querySelectorAll('[data-union-element]').forEach(node=>{node.addEventListener('pointerdown',e=>startCanvasDrag(e,'union',node.dataset.unionId,node.dataset.unionElement));node.addEventListener('click',()=>selectCanvasItem('union',node.dataset.unionId,node.dataset.unionElement));node.addEventListener('keydown',handleCanvasKey)})}
function renderProfessionalCanvas(focusSelector=''){const host=$('professional-svg'),svg=renderGenogramSvg(appState,{view:'professional',showEmotional:appState.settings.showEmotional,interactive:true});host.replaceChildren(svg);attachCanvasInteractions(svg);$('legend').innerHTML=legendHtml(true);if(focusSelector)requestAnimationFrame(()=>host.querySelector(focusSelector)?.focus())}
function renderProfessional(){refreshSelects();renderLists();renderValidation();$('show-emotional').checked=appState.settings.showEmotional;$('genogram-date').value=appState.genogramDate||'';renderProfessionalCanvas()}
function enterProfessionalMode(){renderProfessional();showScreen('professional-screen')}
function selectCanvasItem(kind,id,key=''){selectedPersonId=kind==='person'?id:null;selectedAnnotationId=kind==='annotation'?id:null;selectedUnionElement=kind==='union'?{unionId:id,key}:null;renderLists();renderProfessionalCanvas()}
function startCanvasDrag(event,kind,id,key=''){if(event.button!==undefined&&event.button!==0)return;event.preventDefault();const svg=event.currentTarget.ownerSVGElement,rect=svg.getBoundingClientRect(),view=svg.viewBox.baseVal;if(!rect.width||!rect.height)return;selectCanvasItemState(kind,id,key);if(kind==='person'){const item=getPerson(appState,id);dragState={kind,id,pointerId:event.pointerId,startX:item.x,startY:item.y,startClientX:event.clientX,startClientY:event.clientY,scaleX:view.width/rect.width,scaleY:view.height/rect.height}}else if(kind==='annotation'){const item=getAnnotation(appState,id);dragState={kind,id,pointerId:event.pointerId,startX:item.x,startY:item.y,startClientX:event.clientX,startClientY:event.clientY,scaleX:view.width/rect.width,scaleY:view.height/rect.height}}else{const union=getUnion(appState,id);dragState={kind,id,key,pointerId:event.pointerId,startOffset:finite(union.offsets&&union.offsets[key],0),startClientX:event.clientX,scaleX:view.width/rect.width}}event.currentTarget.classList.add('dragging');window.addEventListener('pointermove',moveCanvasDrag);window.addEventListener('pointerup',endCanvasDrag,{once:true});window.addEventListener('pointercancel',endCanvasDrag,{once:true});renderLists()}
function selectCanvasItemState(kind,id,key=''){selectedPersonId=kind==='person'?id:null;selectedAnnotationId=kind==='annotation'?id:null;selectedUnionElement=kind==='union'?{unionId:id,key}:null}
function moveCanvasDrag(event){if(!dragState||event.pointerId!==dragState.pointerId)return;if(dragState.kind==='person'||dragState.kind==='annotation'){const item=dragState.kind==='person'?getPerson(appState,dragState.id):getAnnotation(appState,dragState.id);if(!item)return;const next=computeDraggedPosition(dragState.startX,dragState.startY,dragState.startClientX,dragState.startClientY,event.clientX,event.clientY,dragState.scaleX,dragState.scaleY);item.x=next.x;item.y=next.y}else{const union=getUnion(appState,dragState.id);if(!union)return;union.offsets=normalizeUnionOffsets(union.offsets);union.offsets[dragState.key]=dragState.startOffset;moveUnionElement(appState,dragState.id,dragState.key,(event.clientX-dragState.startClientX)*dragState.scaleX)}renderProfessionalCanvas()}
function endCanvasDrag(){if(!dragState)return;dragState=null;window.removeEventListener('pointermove',moveCanvasDrag);persist();renderProfessional()}
function handleCanvasKey(event){if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;const personId=event.currentTarget.dataset.personId,annotationId=event.currentTarget.dataset.annotationId,unionId=event.currentTarget.dataset.unionId,key=event.currentTarget.dataset.unionElement,step=event.shiftKey?30:10;event.preventDefault();let selector;if(personId||annotationId){const item=personId?getPerson(appState,personId):getAnnotation(appState,annotationId);if(event.key==='ArrowLeft')item.x-=step;if(event.key==='ArrowRight')item.x+=step;if(event.key==='ArrowUp')item.y-=step;if(event.key==='ArrowDown')item.y+=step;item.x=clamp(item.x,55,1945);item.y=clamp(item.y,60,1140);selectCanvasItemState(personId?'person':'annotation',personId||annotationId);selector=personId?'[data-person-id="'+CSS.escape(personId)+'"]':'[data-annotation-id="'+CSS.escape(annotationId)+'"]'}else{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;moveUnionElement(appState,unionId,key,event.key==='ArrowLeft'?-step:step);selectCanvasItemState('union',unionId,key);selector='[data-union-id="'+CSS.escape(unionId)+'"][data-union-element="'+CSS.escape(key)+'"]'}persist();renderLists();renderProfessionalCanvas(selector)}
function clearPersonForm(){$('person-form').reset();$('person-id').value='';}
function clearUnionForm(){$('union-form').reset();$('union-id').value='';}
function clearAnnotationForm(){$('annotation-form').reset();$('annotation-id').value='';}
function childPeople(){return appState.people.filter(isHuman).sort((a,b)=>a.y-b.y||a.x-b.x);}
function setupFilters(){const cats=['todas',...Object.keys(MINIATURE_GROUPS)];$('category-filters').innerHTML=cats.map(c=>`<button type="button" class="filter-chip ${c===currentCategory?'active':''}" data-category="${escapeHtml(c)}">${c==='todas'?'Todas':c[0].toUpperCase()+c.slice(1)}</button>`).join('');}
function renderMiniatureGallery(query=''){const filtered=MINIATURES.filter(m=>(currentCategory==='todas'||m.category===currentCategory)&&(!query||normalize(`${m.label} ${m.category}`).includes(normalize(query))));$('miniature-gallery').innerHTML=filtered.map(m=>`<button type="button" class="miniature" role="option" data-miniature="${escapeHtml(m.id)}" aria-selected="${!pendingOmitted&&pendingMiniature===m.id}" title="${escapeHtml(m.label)}"><span class="emoji" aria-hidden="true">${m.symbol}</span><small>${escapeHtml(m.label)}</small></button>`).join('')||'<p>No hay resultados.</p>';}
function renderCurrentChoice(){const mini=!pendingOmitted&&MINIATURE_BY_ID[pendingMiniature];$('current-choice').innerHTML=pendingOmitted?'<span>—</span><small>Sin elección por ahora</small>':mini?`<span>${mini.symbol}</span><small>${escapeHtml(mini.label)}</small>`:'<span>?</span><small>Ninguna elegida</small>';const omit=$('omit-choice');omit.setAttribute('aria-pressed',pendingOmitted?'true':'false');omit.textContent=pendingOmitted?'Elegir una miniatura':'Omitir por ahora';}
function renderChildSlot(){const people=childPeople();if(!people.length){toast('La estructura todavía no tiene personas.');enterProfessionalMode();return;}appState.ui.childIndex=clamp(appState.ui.childIndex,0,people.length-1);const p=people[appState.ui.childIndex];pendingMiniature=appState.childResponse.assignments[p.id]||null;pendingOmitted=Boolean(appState.childResponse.omitted[p.id]);$('child-progress').textContent=`${appState.ui.childIndex+1} de ${people.length}`;$('child-person-name').textContent=`${p.name}${p.role?' · '+p.role:''}`;renderCurrentChoice();$('child-explanation').value=appState.childResponse.explanations[p.id]||'';$('child-prev').disabled=appState.ui.childIndex===0;$('confirm-choice').textContent=appState.ui.childIndex===people.length-1?'Ver mi tablero':'Confirmar y seguir';setupFilters();renderMiniatureGallery($('miniature-search').value);}
function enterChildMode(){const v=validateGraph(appState);if(!v.valid||!childPeople().length){toast('Prepara una estructura válida con al menos una persona antes de iniciar.');return;}appState.ui.childIndex=0;persist();renderChildSlot();showScreen('child-screen');}
function finishChildView(){$('child-result-svg').replaceChildren(renderGenogramSvg(appState,{view:'game',showEmotional:false}));showScreen('child-result-screen');}
function renderFinal(){const pro=appState.ui.finalView==='professional';$('final-game-view').className=`button ${pro?'secondary':'primary'}`;$('final-pro-view').className=`button ${pro?'primary':'secondary'}`;$('final-svg').replaceChildren(renderGenogramSvg(appState,{view:pro?'professional':'game',showEmotional:pro}));$('final-legend').innerHTML=legendHtml(pro);}
function showFinal(){renderFinal();showScreen('final-screen');}
function handleRecord(event){const button=event.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;if(action==='edit-person'){const p=getPerson(appState,id);if(!p)return;selectCanvasItemState('person',id);$('person-id').value=p.id;$('person-kind').value=p.kind;$('person-name').value=p.name;$('person-species').value=p.species;$('person-role').value=p.role;$('person-shape').value=p.shape;$('person-deceased').checked=p.deceased;$('person-identified').checked=p.identified;$('person-age').value=p.age??'';$('person-birth-date').value=p.birthDate;$('person-death-date').value=p.deathDate;$('person-name').focus();renderLists();renderProfessionalCanvas();return}if(action==='edit-union'){const u=getUnion(appState,id);if(!u)return;$('union-id').value=u.id;$('union-a').value=u.personA;$('union-b').value=u.personB;$('union-status').value=u.status;$('union-marriage-date').value=u.marriageDate;$('union-divorce-date').value=u.divorceDate;$('union-a').focus();return}if(action==='edit-annotation'){const annotation=getAnnotation(appState,id);if(!annotation)return;selectCanvasItemState('annotation',id);$('annotation-id').value=id;$('annotation-text').value=annotation.text;$('annotation-text').focus();renderLists();renderProfessionalCanvas();return}if(!confirm('¿Eliminar este elemento?'))return;if(action==='delete-person'){removePerson(appState,id);if(selectedPersonId===id)selectedPersonId=null}if(action==='delete-union'){removeUnion(appState,id);if(selectedUnionElement?.unionId===id)selectedUnionElement=null}if(action==='delete-descent')removeDescentLink(appState,id);if(action==='delete-emotion')removeEmotionalLink(appState,id);if(action==='delete-household')appState.households=appState.households.filter(h=>h.id!==id);if(action==='delete-annotation'){removeAnnotation(appState,id);if(selectedAnnotationId===id)selectedAnnotationId=null}persist();renderProfessional();toast('Elemento eliminado.')}
function bindEvents(){
  $('choose-professional').addEventListener('click',()=>{if(currentRecord())enterProfessionalMode()});$('choose-child').addEventListener('click',()=>{if(currentRecord())enterChildMode()});$('new-genogram').addEventListener('click',()=>{$('new-genogram-name').value='';$('new-genogram-error').textContent='';$('new-genogram-name').focus()});
  $('new-genogram-form').addEventListener('submit',event=>{event.preventDefault();const checked=validateGenogramName($('new-genogram-name').value);$('new-genogram-error').textContent=checked.error;if(!checked.valid)return;createAndOpenGenogram(checked.name);event.target.reset();enterProfessionalMode();toast('Genograma creado.')});
  $('import-v5').addEventListener('click',async()=>{const file=$('import-v5-file').files[0],status=$('import-v5-status');if(!file){status.textContent='Selecciona un archivo JSON de V5.';return}try{const raw=JSON.parse(await file.text()),incoming=migrateV5Library(raw);if(!incoming.items.length)throw new Error('El archivo no contiene genogramas válidos.');libraryState=mergeImportedLibrary(libraryState,incoming);if(!currentGenogramId&&libraryState.currentId){currentGenogramId=libraryState.currentId;appState=sanitizeState(libraryState.items.find(item=>item.id===currentGenogramId)?.state)}saveLibrary(libraryState);renderLibrary();status.textContent=incoming.items.length+' genograma(s) importado(s) o actualizado(s), sin duplicar IDs.'}catch(error){status.textContent='No se pudo importar: '+error.message}});
  $('genogram-library').addEventListener('click',event=>{const button=event.target.closest('[data-library-action]');if(!button)return;const record=libraryState.items.find(item=>item.id===button.dataset.id);if(!record)return;if(button.dataset.libraryAction==='open'){openGenogram(record.id);toast('Genograma abierto.');return}if(!confirm('¿Eliminar “'+record.name+'”? Esta acción borra solo este genograma de este navegador.'))return;libraryState=deleteGenogramFromLibrary(libraryState,record.id);if(currentGenogramId===record.id){currentGenogramId=null;appState=createInitialState();selectedPersonId=null;selectedAnnotationId=null;selectedUnionElement=null}saveLibrary(libraryState);renderLibrary();toast('Genograma eliminado.')});
  $('rename-genogram-form').addEventListener('submit',event=>{event.preventDefault();if(!currentGenogramId)return;const checked=validateGenogramName($('rename-genogram-name').value);$('rename-genogram-error').textContent=checked.error;if(!checked.valid)return;appState.genogramDate=$('genogram-date').value;libraryState=updateGenogramInLibrary(libraryState,currentGenogramId,appState).library;libraryState=renameGenogramInLibrary(libraryState,currentGenogramId,checked.name).library;saveLibrary(libraryState);renderLibrary();renderProfessionalCanvas();toast('Datos del genograma actualizados.')});
  $('load-example').addEventListener('click',()=>{const name='Familia ficticia '+(libraryState.items.length+1);createAndOpenGenogram(name,createExampleState());selectedPersonId=null;selectedAnnotationId=null;selectedUnionElement=null;enterProfessionalMode();toast('Plantilla ficticia creada como genograma nuevo.')});
  $('person-form').addEventListener('submit',event=>{event.preventDefault();try{const input={kind:$('person-kind').value,name:$('person-name').value,species:$('person-species').value,role:$('person-role').value,shape:$('person-shape').value,deceased:$('person-deceased').checked,identified:$('person-identified').checked,age:$('person-age').value,birthDate:$('person-birth-date').value,deathDate:$('person-death-date').value},id=$('person-id').value;if(id)updatePerson(appState,id,input);else{const person=addPerson(appState,input);selectCanvasItemState('person',person.id)}clearPersonForm();persist();renderProfessional();toast(input.kind==='pet'?'Mascota guardada.':'Persona guardada.')}catch(error){toast(error.message)}});$('cancel-person').addEventListener('click',clearPersonForm);
  $('union-form').addEventListener('submit',event=>{event.preventDefault();try{const input={personA:$('union-a').value,personB:$('union-b').value,status:$('union-status').value,marriageDate:$('union-marriage-date').value,divorceDate:$('union-divorce-date').value},id=$('union-id').value;if(id)updateUnion(appState,id,input);else addUnion(appState,input);clearUnionForm();persist();renderProfessional();toast('Unión guardada.')}catch(error){toast(error.message)}});$('cancel-union').addEventListener('click',clearUnionForm);
  $('descent-form').addEventListener('submit',event=>{event.preventDefault();try{const [sourceType,sourceId]=$('descent-source').value.split(':');addDescentLink(appState,{sourceType,sourceId,childId:$('descent-child').value,type:$('descent-type').value});persist();renderProfessional();toast('Filiación añadida.')}catch(error){toast(error.message)}});
  $('emotional-form').addEventListener('submit',event=>{event.preventDefault();try{addEmotionalLink(appState,{personA:$('emotion-a').value,personB:$('emotion-b').value,type:$('emotion-type').value});persist();renderProfessional();toast('Relación añadida.')}catch(error){toast(error.message)}});
  $('household-form').addEventListener('submit',event=>{event.preventDefault();try{addHousehold(appState,{name:$('household-name').value,memberIds:[...$('household-members').querySelectorAll(':checked')].map(x=>x.value)});event.target.reset();persist();renderProfessional();toast('Hogar creado.')}catch(error){toast(error.message)}});
  $('annotation-form').addEventListener('submit',event=>{event.preventDefault();try{const id=$('annotation-id').value,text=$('annotation-text').value;if(id)updateAnnotation(appState,id,{text});else{const annotation=addAnnotation(appState,{text});selectCanvasItemState('annotation',annotation.id)}clearAnnotationForm();persist();renderProfessional();toast('Texto independiente guardado.')}catch(error){toast(error.message)}});$('cancel-annotation').addEventListener('click',clearAnnotationForm);
  ['people-list','union-list','descent-list','emotion-list','household-list','annotation-list'].forEach(id=>$(id).addEventListener('click',handleRecord));$('show-emotional').addEventListener('change',event=>{appState.settings.showEmotional=event.target.checked;persist();renderProfessionalCanvas()});$('start-child').addEventListener('click',enterChildMode);$('go-final').addEventListener('click',showFinal);$('exit-professional').addEventListener('click',()=>showScreen('welcome-screen'));$('reset-session').addEventListener('click',()=>{if(!confirm('¿Vaciar este genograma? Se borrarán su estructura, relaciones, textos y elecciones; los demás genogramas seguirán guardados.'))return;appState=createInitialState();selectedPersonId=null;selectedAnnotationId=null;selectedUnionElement=null;persist();renderProfessional();toast('Genograma vaciado.')});
  $('category-filters').addEventListener('click',event=>{const button=event.target.closest('[data-category]');if(!button)return;currentCategory=button.dataset.category;setupFilters();renderMiniatureGallery($('miniature-search').value)});$('miniature-search').addEventListener('input',event=>renderMiniatureGallery(event.target.value));$('miniature-gallery').addEventListener('click',event=>{const button=event.target.closest('[data-miniature]');if(!button)return;pendingMiniature=button.dataset.miniature;pendingOmitted=false;renderCurrentChoice();renderMiniatureGallery($('miniature-search').value)});$('omit-choice').addEventListener('click',()=>{pendingOmitted=!pendingOmitted;if(pendingOmitted)pendingMiniature=null;renderCurrentChoice();renderMiniatureGallery($('miniature-search').value)});$('confirm-choice').addEventListener('click',()=>{if(!pendingOmitted&&!pendingMiniature){toast('Elige una miniatura u omite a esta persona para continuar.');return}const people=childPeople(),person=people[appState.ui.childIndex];if(pendingOmitted)omitPerson(appState,person.id,$('child-explanation').value);else assignMiniature(appState,person.id,pendingMiniature,$('child-explanation').value);persist();if(appState.ui.childIndex<people.length-1){appState.ui.childIndex++;renderChildSlot();window.scrollTo(0,0)}else finishChildView()});$('child-prev').addEventListener('click',()=>{if(appState.ui.childIndex>0){appState.ui.childIndex--;renderChildSlot();window.scrollTo(0,0)}});$('result-back').addEventListener('click',()=>{appState.ui.childIndex=Math.max(0,childPeople().length-1);renderChildSlot();showScreen('child-screen')});$('finish-child').addEventListener('click',()=>{appState.childResponse.finishedAt=new Date().toISOString();persist();showFinal()});
  $('adult-exit').addEventListener('click',()=>{const a=3+Math.floor(Math.random()*7),b=2+Math.floor(Math.random()*7);adultSum=a+b;$('adult-question').textContent=a+' + '+b+' =';$('adult-answer').value='';$('adult-error').textContent='';$('adult-dialog').showModal()});$('adult-confirm').addEventListener('click',event=>{event.preventDefault();if(Number($('adult-answer').value)!==adultSum){$('adult-error').textContent='Inténtalo de nuevo.';return}$('adult-dialog').close();enterProfessionalMode()});$('final-game-view').addEventListener('click',()=>{appState.ui.finalView='game';persist();renderFinal()});$('final-pro-view').addEventListener('click',()=>{appState.ui.finalView='professional';persist();renderFinal()});$('final-edit').addEventListener('click',enterProfessionalMode);$('final-home').addEventListener('click',()=>showScreen('welcome-screen'));
}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',()=>{bindEvents();setupFilters();renderLibrary();});
if(typeof module!=='undefined'&&module.exports)module.exports={APP_VERSION,persistenceName:V6_STORAGE,MINIATURES,MINIATURE_BY_ID,createInitialState,createExampleState,sanitizeState,normalizeGenogramName,validateGenogramName,createLibrary,sanitizeLibrary,migrateV5Library,mergeImportedLibrary,createGenogramRecord,addGenogramToLibrary,updateGenogramInLibrary,renameGenogramInLibrary,deleteGenogramFromLibrary,addPerson,updatePerson,removePerson,addUnion,updateUnion,removeUnion,addDescentLink,removeDescentLink,addEmotionalLink,removeEmotionalLink,addHousehold,addAnnotation,updateAnnotation,removeAnnotation,validateGraph,hasAncestryPath,sourceParentIds,computeUnionGeometry,unionElementPosition,moveUnionElement,computeDescentGeometry,computeHouseholdGeometry,computeEmotionalGeometry,computeDraggedPosition,assignMiniature,omitPerson,pairKey};
